  /** 우회전 (537) */
  right: [[-0.12, 0.00], [-0.12, 3.08], [-0.11, 3.20], [-0.10, 3.33], [-0.07, 3.48], [-0.02, 3.65], [0.06, 3.81], [0.17, 3.96], [0.32, 4.10], [0.52, 4.22], [0.52, 4.81], [1.12, 3.88], [0.52, 2.85], [0.52, 3.48], [0.46, 3.47], [0.40, 3.45], [0.33, 3.42], [0.27, 3.37], [0.21, 3.31], [0.16, 3.24], [0.13, 3.15], [0.12, 3.05], [0.12, 0.01]],
  /** 직진 및 좌회전 (538) */
  straightLeft: [[0.11, 0.00], [0.11, 2.71], [0.29, 2.71], [-0.04, 4.89], [-0.31, 2.70], [-0.12, 2.70], [-0.12, 1.52], [-0.15, 1.55], [-0.19, 1.59], [-0.24, 1.63], [-0.29, 1.68], [-0.34, 1.72], [-0.39, 1.76], [-0.43, 1.79], [-0.47, 1.81], [-0.47, 2.41], [-0.98, 1.47], [-0.47, 0.65], [-0.47, 1.11], [-0.46, 1.13], [-0.43, 1.14], [-0.38, 1.13], [-0.32, 1.11], [-0.27, 1.06], [-0.21, 0.99], [-0.15, 0.90], [-0.11, 0.78], [-0.11, 0.01]],
  /** 직진 및 우회전 (538) */
  straightRight: [[-0.11, 0.00], [-0.11, 2.71], [-0.30, 2.71], [0.04, 4.89], [0.31, 2.70], [0.12, 2.70], [0.12, 1.52], [0.15, 1.55], [0.19, 1.59], [0.24, 1.63], [0.29, 1.68], [0.34, 1.72], [0.39, 1.76], [0.43, 1.79], [0.47, 1.81], [0.47, 2.41], [0.98, 1.47], [0.47, 0.65], [0.47, 1.11], [0.46, 1.13], [0.43, 1.14], [0.38, 1.13], [0.33, 1.11], [0.27, 1.06], [0.21, 0.99], [0.15, 0.90], [0.11, 0.78], [0.11, 0.01]],
  /** 유턴 (539) */
